// Draw fish - create a fish school effect
function drawFish(x, y, size, tail, bodyColor, eyeColor) {
    // Main body
    ctx.fillStyle = bodyColor;
    ctx.fillRect(x - size, y - size/2, size*2, size);

    // Tail
    ctx.fillStyle = tail;
    ctx.fillRect(x - size, y - size/4, tail, size/2);

    // Eye
    ctx.fillStyle = eyeColor;
    ctx.fillRect(x + size/4, y - size/4, 8, 8);

    // Fin
    ctx.fillStyle = BLACK;
    ctx.fillRect(x - size/2, y - size/4, 10, 5);
}

