function drawFlower(x, y, size, color) {
    // Stem
    ctx.fillStyle = '#228B22';
    ctx.fillRect(x - 2, y, 4, size * 0.6);

    // Leaves
    ctx.fillStyle = '#32CD32';
    ctx.fillRect(x - 8, y + size * 0.6, 16, 4);

    // Center
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, size * 0.3, 0, Math.PI * 2);
    ctx.fill();

    // Petals
    ctx.fillStyle = '#FF69B4';
    for (let i = 0; i < 8; i++) {
        const angle = (i / 8) * Math.PI * 2;
        const cx = x + Math.cos(angle) * size * 0.4;
        const cy = y + Math.sin(angle) * size * 0.4;
        ctx.beginPath();
        ctx.arc(cx, cy, size * 0.25, 0, Math.PI * 2);
        ctx.fill();
    }
}

