// Draw spiral pattern
function drawSpiral(x, y, r, depth) {
    if (depth > 0) {
        // Draw arc at current position
        ctx.fillStyle = ACCENT;
        ctx.globalAlpha = 0.3 + 0.2 * Math.sin(depth); // Diverging transparency
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fill();

        // Recursive calls for spiral arms
        drawSpiral(x + r * Math.cos(0), y + r * Math.sin(0), r * 0.7, depth - 1);
        drawSpiral(x + r * Math.cos(Math.PI/4), y + r * Math.sin(Math.PI/4), r * 0.7, depth - 1);
        drawSpiral(x + r * Math.cos(-Math.PI/4), y + r * Math.sin(-Math.PI/4), r * 0.7, depth - 1);
    }
}

